#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);

    // Allocate DP table (plen+1) x (tlen+1)
    bool **dp = malloc((plen + 1) * sizeof(bool *));
    if (!dp) {
        perror("malloc");
        return 1;
    }
    for (size_t i = 0; i <= plen; ++i) {
        dp[i] = calloc(tlen + 1, sizeof(bool));
        if (!dp[i]) {
            perror("calloc");
            for (size_t k = 0; k < i; ++k) free(dp[k]);
            free(dp);
            return 1;
        }
    }

    dp[0][0] = true; // empty pattern matches empty text

    // pattern prefixes against empty text: only '*' can match
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }

    // fill DP table
    for (size_t i = 1; i <= plen; ++i) {
        char pc = pattern[i - 1];
        for (size_t j = 1; j <= tlen; ++j) {
            char tc = text[j - 1];
            if (pc == '*') {
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc == '?') {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = (pc == tc) && dp[i - 1][j - 1];
            }
        }
    }

    if (dp[plen][tlen])
        puts("MATCH");
    else
        puts("NO_MATCH");

    // clean up
    for (size_t i = 0; i <= plen; ++i)
        free(dp[i]);
    free(dp);
    return 0;
}
